DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `orders` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `invoice_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gender` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `city_id` int(10) unsigned DEFAULT 0,
  `district_id` int(10) unsigned DEFAULT 0,
  `ward_id` int(10) unsigned DEFAULT 0,
  `address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `note` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `price_total` int(11) DEFAULT 0,
  `price_shipping` int(11) DEFAULT 0,
  `price_discount` int(11) DEFAULT 0,
  `viewer` int(11) DEFAULT 0,
  `order_status` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'awaiting',
  `shipping_status` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT 'awaiting',
  `payment_status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'awaiting',
  `payment_method` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'cash_on_delivery',
  `coupon_code` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=313 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

